def nb_patterns(I,O,fc,bg):
    Hh,Ww=I.shape
    d=collections.defaultdict(lambda: [0,0])
    for y in range(1,Hh-1):
        for x in range(1,Ww-1):
            if I[y][x]==0:
                pat=tuple(1 if I[y+dy][x+dx]==bg else 0 for dy in(-1,0,1) for dx in(-1,0,1) if not(dy==0 and dx==0))
                d[pat][1 if O[y][x]==fc else 0]+=1
    return d
