def test_mirror(I,O,fc,bg,c0):
    Hh,Ww=I.shape; mis=0; tested=0
    for y in range(Hh):
        for x in range(Ww):
            if I[y][x]==0:
                ym, xm = x+c0, y-c0
                if 0<=ym<Hh and 0<=xm<Ww and I[ym][xm]!=0:
                    tested+=1
                    if (I[ym][xm]==bg) != (O[y][x]==fc):
                        mis+=1
    return mis, tested
