def diag_runs(I,O,fc,thr):
    Hh,Ww=I.shape
    # label slope-1 diagonal runs of zeros
    fill=np.zeros_like(O,dtype=bool)
    for start in [(y,0) for y in range(Hh)]+[(0,x) for x in range(1,Ww)]:
        y,x=start; run=[]
        while 0<=y<Hh and 0<=x<Ww:
            if I[y][x]==0: run.append((y,x))
            else:
                if len(run)>=thr:
                    for yy,xx in run: fill[yy][xx]=True
                run=[]
            y+=1; x+=1
        if len(run)>=thr:
            for yy,xx in run: fill[yy][xx]=True
    mis=sum(1 for y in range(Hh) for x in range(Ww) if I[y][x]==0 and fill[y][x]!=(O[y][x]==fc))
    return mis, int(fill.sum())
