def refl_pred(I,O,fc,bg,mode,s0):
    Hh,Ww=I.shape; mis=0
    for y in range(Hh):
        for x in range(Ww):
            if I[y][x]==0:
                if mode=='anti': ym,xm = s0-x, s0-y
                else: ym,xm = x-s0, y+s0
                if 0<=ym<Hh and 0<=xm<Ww:
                    p = (I[ym][xm]==bg) if mode=='anti' else (I[ym][xm]==bg)
                    if p!=(O[y][x]==fc): mis+=1
    return mis
