def stamp_rule2(I,O,fc,bg,seeds,ret='mis'):
    Hh,Ww=I.shape
    fill=np.zeros_like(O,dtype=bool)
    placements=[]
    for dy in range(-Hh,Hh):
        for dx in range(-Ww,Ww):
            cells_=[(y+dy,x+dx) for y,x in seeds]
            if all(0<=y<Hh and 0<=x<Ww and I[y][x]!=bg for y,x in cells_):
                placements.append((dy,dx,cells_))
                for y,x in cells_: fill[y][x]=True
    mis=[(y,x) for y in range(Hh) for x in range(Ww) if I[y][x]==0 and fill[y][x]!=(O[y][x]==fc)]
    return mis, placements
